CREATE VIEW mart_recommendation_combined_v1 AS SELECT t.GameKey, t.GameID, t.GameTitle, t.PlayStatusName, t.explicit_preference_percentile, t.similarity_margin_percentile, t.taste_affinity_score, t.taste_affinity_status, p.SpecialAccessoryRequired, p.ControlSchemeRisk, p.RhythmFlag, p.SHMUPFlag, p.SoulslikeFlag, p.MitigationAvailable, p.playability_adjustment, p.playability_status, p.hard_exclusion_flag, p.exclusion_reason, CASE  WHEN ((p.hard_exclusion_flag = CAST('t' AS BOOLEAN))) THEN (NULL) WHEN ((t.taste_affinity_score IS NULL)) THEN (NULL) ELSE round((t.taste_affinity_score + p.playability_adjustment), 2) END AS provisional_recommendation_score, CASE  WHEN ((p.hard_exclusion_flag = CAST('t' AS BOOLEAN))) THEN ('Excluded') WHEN ((t.taste_affinity_score IS NULL)) THEN ('Insufficient Metadata') WHEN ((p.playability_status = 'Unknown')) THEN ('Affinity Scored / Playability Unknown') WHEN ((p.playability_status = 'High Risk')) THEN ('High Playability Risk') WHEN ((p.playability_status = 'Playable With Mitigation')) THEN ('Conditional Recommendation') ELSE 'Eligible' END AS recommendation_status FROM mart_taste_affinity_v1 AS t LEFT JOIN mart_playability_v1 AS p ON ((p.GameKey = t.GameKey));
